#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-14

# Test: every published Lab page carries the lab chrome exactly once
#
# Social traffic lands on the raw /lab/<slug>.html pages, and most of them had
# no link back to the site, no share card and no page_view. lab-manifest.mjs now
# injects a head block (Open Graph + Twitter meta) and a body block (footer +
# first-party beacon) into every public/lab copy. This suite proves, on a
# fixture repo and through the same --check oracle CI runs:
#   1. each marker, og:image and the footer land exactly once per page,
#      including a page with no </head> or </body> and a page with a second
#      "</body>" inside a script string;
#   2. regenerating is byte-identical (idempotent), also when the source is
#      absent and the committed, already-injected copy is the input;
#   3. the author's source page is never modified;
#   4. an author's own og:image wins and is not duplicated;
#   5. title text is attribute-escaped;
#   6. a public copy without the chrome fails --check (so a new page cannot
#      ship without it), and the clean tree passes.
#
# Occurrence counts use node on a FILE, never grep -c (that counts lines) and
# never a pipe (#603).

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
TOOL="$REPO_ROOT/docs/site/scripts/lab-manifest.mjs"

FAILED=0
CHECKED=0

if [[ ! -f "$TOOL" ]]; then
  echo "FAIL: generator missing: $TOOL"
  exit 1
fi

WORK="$(mktemp -d "${TMPDIR:-/tmp}/lab-chrome.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT
OUT="$WORK/out.txt"

ok()  { CHECKED=$((CHECKED+1)); echo "PASS: $1"; }
bad() { CHECKED=$((CHECKED+1)); FAILED=$((FAILED+1)); echo "FAIL: $1"; }

gen()   { node "$TOOL" --repo "$1" >"$OUT" 2>&1; }
check() { node "$TOOL" --check --repo "$1" >"$OUT" 2>&1; }

# occurrences <file> <literal>: non-overlapping count of a literal substring.
occurrences() {
  node -e 'const t=require("fs").readFileSync(process.argv[1],"utf8");console.log(t.split(process.argv[2]).length-1)' "$1" "$2"
}

expect_once() { # <file> <literal> <label>
  local n
  n="$(occurrences "$1" "$2")"
  if [[ "$n" == "1" ]]; then ok "$3"; else bad "$3 (found $n)"; fi
}

R="$WORK/repo"
mkdir -p "$R/docs/feat--x" "$R/docs/site/lab-manifest"

# Full document.
cat > "$R/docs/feat--x/full.html" <<'HTML'
<!doctype html>
<html><head><meta charset="utf-8"><title>Full page</title></head>
<body><main><h1>Full</h1></main></body></html>
HTML
# Fragment-style page: no </head>, no </body>.
printf '<!doctype html><title>Bare page</title><p>bare' > "$R/docs/feat--x/bare.html"
# A decoy </body> inside a script string, before the real one.
cat > "$R/docs/feat--x/decoy.html" <<'HTML'
<!doctype html>
<html><head><title>Decoy "quoted" & page</title></head>
<body><script>var s = "<html><body>x</body></html>";</script><p>after</p>
</body></html>
HTML
# The author already declares og:image.
cat > "$R/docs/feat--x/own-og.html" <<'HTML'
<!doctype html>
<html><head><title>Own OG</title><meta property="og:image" content="https://example.com/own.png"></head>
<body><p>own</p></body></html>
HTML

for s in full bare decoy own-og; do
  printf '{"slug":"%s","source":"docs/feat--x/%s.html","date":"2026-09-14"}\n' "$s" "$s" \
    > "$R/docs/site/lab-manifest/$s.json"
done
cp "$R/docs/feat--x/full.html" "$WORK/full.orig.html"

if ! gen "$R"; then cat "$OUT"; echo "FAIL: generate"; exit 1; fi
PUB="$R/docs/site/public/lab"

# ---------------------------------------------------------------- 1. exactly once
for s in full bare decoy own-og; do
  f="$PUB/$s.html"
  expect_once "$f" "<!-- ork-lab-head:start -->" "$s: head block once"
  expect_once "$f" "<!-- ork-lab-chrome:start -->" "$s: chrome block once"
  expect_once "$f" 'id="ork-lab-chrome"' "$s: footer once"
  expect_once "$f" 'property="og:image"' "$s: og:image once"
  expect_once "$f" 'href="/docs/getting-started/installation"' "$s: install link once"
done

# Placement: the head block precedes </head>, the footer precedes the REAL </body>.
if node -e '
  const t=require("fs").readFileSync(process.argv[1],"utf8");
  const head=t.indexOf("<!-- ork-lab-head:end -->"), hc=t.indexOf("</head>");
  const chrome=t.indexOf("<!-- ork-lab-chrome:end -->"), bc=t.lastIndexOf("</body>");
  const decoy=t.indexOf("x</body>");
  process.exit(head>=0 && head<hc && chrome>=0 && chrome<bc && chrome>decoy ? 0 : 1);
' "$PUB/decoy.html"; then
  ok "decoy: head before first </head>, footer before the last </body>, after the decoy"
else
  bad "decoy: chrome placed at the wrong position"
fi

# ---------------------------------------------------------------- 2. idempotent
cp -R "$PUB" "$WORK/pub1"
gen "$R"
if diff -r "$WORK/pub1" "$PUB" >"$OUT" 2>&1; then
  ok "regenerate is byte-identical"
else
  bad "regenerate changed bytes"; cat "$OUT"
fi
# Source absent: the committed, injected copy is the input.
mv "$R/docs/feat--x/full.html" "$WORK/full.moved.html"
gen "$R"
if cmp -s "$WORK/pub1/full.html" "$PUB/full.html"; then
  ok "fallback to the committed copy renders the same bytes (no double injection)"
else
  bad "fallback to the committed copy changed bytes"
fi
mv "$WORK/full.moved.html" "$R/docs/feat--x/full.html"

# ---------------------------------------------------------------- 3. source untouched
if cmp -s "$WORK/full.orig.html" "$R/docs/feat--x/full.html"; then
  ok "author source page is not modified"
else
  bad "author source page was modified"
fi

# ---------------------------------------------------------------- 4. own og:image
if [[ "$(occurrences "$PUB/own-og.html" 'https://example.com/own.png')" == "1" && \
      "$(occurrences "$PUB/own-og.html" '/opengraph-image"')" == "1" ]]; then
  # The default image still appears once, as twitter:image only.
  ok "own-og: author og:image kept, default not added as og:image"
else
  bad "own-og: author og:image handling wrong"
fi

# ---------------------------------------------------------------- 5. escaping
expect_once "$PUB/decoy.html" '<meta property="og:title" content="Decoy &quot;quoted&quot; &amp; page">' "decoy: og:title attribute-escaped"
expect_once "$PUB/decoy.html" '<meta name="twitter:title" content="Decoy &quot;quoted&quot; &amp; page">' "decoy: twitter:title attribute-escaped"

# ---------------------------------------------------------------- 6. --check
if check "$R"; then ok "clean tree passes --check"; else bad "clean tree fails --check"; cat "$OUT"; fi
cp "$R/docs/feat--x/full.html" "$PUB/full.html"
if check "$R"; then
  bad "--check passed a public copy without the lab chrome"
elif [[ "$(occurrences "$OUT" 'missing the lab chrome')" == "1" ]]; then
  ok "--check fails a public copy without the lab chrome, and names why"
else
  bad "--check failed without naming the missing chrome"; cat "$OUT"
fi

echo
echo "lab chrome: $CHECKED checks, $FAILED failed"
[[ "$FAILED" -eq 0 ]]
